mapper.select:
SELECT id, name, order_num eventNumber, appear_time, subject_address, handle_status, event_source, lable, incident_area, examine_status, take_place, take_address, community, send_time, community_code, audit_push_time, system_source, unit_source, unit_username, decision_person_name, read_person_name FROM event_info ei WHERE 1=1
AND (ei.examine_status = 0 or ei.examine_status is null)
AND ei.examine_status = #{examineStatus}
AND ei.lable = #{appealSource}
AND ei.handle_status = #{handleStatus}
AND ei.incident_area = #{incidentArea}
AND ei.appear_time BETWEEN #{beginDate} and #{endDate}
AND ei.created_time BETWEEN #{createDate} and #{createEndDate}
AND ei.`name` LIKE CONCAT('%',#{name},'%')
AND ei.community_code LIKE CONCAT(#{departmentCode},'%')
AND ei.community_code = #{departmentCode}
AND ei.audit_push_time BETWEEN #{pushBeginDate} and #{pushEndDate}
and ei.is_audit='1'
and ei.street_name LIKE CONCAT('%', #{streetName},'%')
and ( ei.decision_person_id LIKE CONCAT('%', #{userId},'%') or ei.audit_user_id = #{auditUserId} )
and ei.decision_person_id LIKE CONCAT('%', #{userId},'%')
order by ei.send_time DESC
limit 5

SELECT ei.id, ei. NAME, ei.event_number, ei.appear_time, ei.subject_address, ei.handle_status, ei.event_source, ei.incident_area, ei.lable, ei.take_place, ei.take_address, ei.system_source, ei.unit_source, ei.send_time, ei.unit_username, ei.decision_person_name, ei.read_person_name FROM event_info ei LEFT JOIN event_comment ec ON ei.id = ec.event_id WHERE 1=1
and ec.user_id = #{userId}
and ec.receive_code = #{receiveCode}
and ei.read_person_id LIKE CONCAT('%',#{readPersonId},'%')
and ec.id is not null group by ei.id order by ec.created_time desc

SELECT id, NAME, event_number, appear_time, subject_address, handle_status, event_source, event_class, lable, incident_area, examine_status, take_place, take_address, community, community_code, event_source_class, related_field, area_distribution, organizer, event_type, emergency_lable, street, street_code FROM event_info ei WHERE 1=1
AND ei.appear_time BETWEEN #{beginDate} and #{endDate}
AND ei.community_code LIKE CONCAT(#{departmentCode},'%')
AND ei.community_code = #{departmentCode}
AND ei.`name` LIKE CONCAT('%',#{name},'%')
AND ei.incident_area = #{incidentArea}
AND ei.handle_status = #{handleStatus}
AND ei.appeal_source = #{appealSource}
AND ei.danger_level = #{dangerLevel}
AND ei.event_class = #{eventClass}
AND ei.event_source_class = #{eventSourceClass}
AND ei.emergency_lable = #{emergencyLable}
AND ei.area_distribution = #{areaDistribution}
AND ei.related_field = #{relatedField}
AND ei.organizer = #{organizer}
AND ei.event_type = #{eventType}
and (ei.is_audit IS NULL or ei.is_audit='' OR ei.is_audit='0') order by ei.appear_time DESC
